True from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            for y, x in q:
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, comp))
    # Fill gaps in near-solid rectangular objects (cells overpainted by stray colors).
    for color, comp in comps:
        if len(comp) < 4:
            continue
        r0=min(r for r,c in comp); r1=max(r for r,c in comp)
        c0=min(c for r,c in comp); c1=max(c for r,c in comp)
        area=(r1-r0+1)*(c1-c0+1)
        if area >= len(comp) and len(comp)/area >= 0.70:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if grid[r][c] != color:
                        out[r][c] = color
    # Remove isolated speckles not absorbed by a rectangle.
    for color, comp in comps:
        if len(comp) == 1:
            r,c=comp[0]
            if out[r][c] == color:
                out[r][c] = bg
    return out
